const SCHEMA = 3;
const migrations = {
  1: (s) => ({ ...s, showLabels: s.labels ?? true }),
  2: (s) => ({ ...s, opacity: Math.min(1, Math.max(0, s.opacity ?? 0.8)) }),
};

export function upgrade(stored, defaults) {
  if (!stored || typeof stored !== "object") return { v: SCHEMA, data: { ...defaults } };
  let v = Number.isInteger(stored.v) ? stored.v : 1;
  let data = { ...defaults, ...(stored.data ?? stored) };
  while (v < SCHEMA) {
    data = migrations[v] ? migrations[v](data) : data;
    v++;
  }
  return { v: SCHEMA, data };
}

