export function wrapMethod(target, name, wrapper) {
  const original = target?.[name];
  if (typeof original !== "function") {
    console.error(`my-mod: ${name} not found, staying vanilla`);
    return false;
  }
  target[name] = function (...args) {
    return wrapper.call(this, original, args);
  };
  return true;
}

