const FLAG = Symbol.for("my-mod.patched");
const VERSION = "1.4.0";

export function patchOnce(target, apply) {
  if (!target) return false;
  if (target[FLAG] === VERSION) return false; // this version already patched it
  apply(target);
  Object.defineProperty(target, FLAG, { value: VERSION, configurable: true });
  return true;
}

