export function previewModifier(modifierId, ctx) {
  const mod = GameInfo.Modifiers.lookup(modifierId);
  const dyn = mod && GameInfo.DynamicModifiers.lookup(mod.ModifierType);
  const handler = dyn && HANDLERS[dyn.EffectType];
  if (!handler) return null; // unknown effect: no preview, never a guess
  const args = {};
  for (const a of GameInfo.ModifierArguments) {
    if (a.ModifierId === modifierId) args[a.Name] = a.Value;
  }
  return handler(args, ctx);
}

