export function sendOwnCityRequest(cityID, operation, args) {
  const city = Cities.get(cityID);
  if (!city || city.owner !== GameContext.localPlayerID) return false; // own entities only
  const check = Game.CityOperations.canStart(cityID, operation, args, false);
  if (!check.Success) return false;
  Game.CityOperations.sendRequest(cityID, operation, args);
  return true;
}

