export function confirm(read, expected, { timeoutMs = 3000, everyMs = 50 } = {}) {
  return new Promise((resolve) => {
    const start = Date.now();
    const tick = () => {
      if (read() === expected) return resolve({ landed: true, ms: Date.now() - start });
      if (Date.now() - start >= timeoutMs) return resolve({ landed: false });
      setTimeout(tick, everyMs);
    };
    tick();
  });
}

