// One path and one fill per colour, never one per shape.
export function paintHexes(ctx, hexesByColor) {
  for (const [color, hexes] of hexesByColor) {
    ctx.beginPath();
    for (const h of hexes) {
      ctx.moveTo(h.x + h.w / 2, h.y);
      ctx.lineTo(h.x + h.w, h.y + h.h / 4);
      ctx.lineTo(h.x + h.w, h.y + (3 * h.h) / 4);
      ctx.lineTo(h.x + h.w / 2, h.y + h.h);
      ctx.lineTo(h.x, h.y + (3 * h.h) / 4);
      ctx.lineTo(h.x, h.y + h.h / 4);
      ctx.closePath();
    }
    ctx.fillStyle = color;
    ctx.fill();
  }
}

const markers = new Map(); // id -> element

export function syncMarkers(layer, items) {
  const seen = new Set();
  for (const item of items) {
    let el = markers.get(item.id);
    if (!el) {
      el = document.createElement("div");
      el.className = "my-mod-marker";
      layer.appendChild(el);
      markers.set(item.id, el);
    }
    el.style.transform = `translate(${item.x}px, ${item.y}px)`;
    el.style.backgroundColor = item.color;
    seen.add(item.id);
  }
  for (const [id, el] of markers) {
    if (!seen.has(id)) { el.remove(); markers.delete(id); }
  }
}

